window.VERBDATA=window.VERBDATA||{};VERBDATA["c2-neungryul-oh-34"]={"level":"고등","grade":"공통영어2","pub":"능률(오)","school":"주성고","term":"2학기 기말고사","lessons":[{"name":"3과","parts":[{"name":"❶","title":"문화유산 구하기 · Rescuing Cultural Treasures","n":4},{"name":"❷","title":"파괴를 막는 것부터 보물을 구하는 것까지 · From Preventing Destruction to Saving Treasures","n":11},{"name":"❸","title":"알타우제에서의 시간을 다투는 경주 · A Race against the Clock at Altaussee","n":11},{"name":"❹","title":"두 달 안에 옮겨야 하는 불가능한 임무 · Moving Everything in Two Months","n":7},{"name":"❺","title":"모뉴먼츠 맨의 지속적인 영향 · The Continuing Impact of the Monuments Men","n":8},{"name":"❻","title":"당신의 언어를 잃지 마라! · Don’t Lose Your Language!","n":6}],"items":[{"ko":"제2차 세계대전 동안, 대단히 귀중한 예술 작품들을 파괴로부터 지키기 위해 모든 것을 건 한 무리의 사람들이 있었다.","en":"During World War II, there ___[be] a group of people who ___[risk] everything ___[protect] priceless works of art from ruin.","ans":["was","risked","to protect"],"part":0,"why":["there(~이 있다) 뒤 주어 a group(한 무리)이 단수라서 단수 과거동사 [유도부사 구문]","who(~하는) 절 안에서 과거 이야기라 과거형 동사 [주격 관계대명사]","‘~하기 위해’(목적)를 뜻하는 부사적 용법의 to부정사"],"jj":[{"e":["During World War II,","there was a group of people","who risked everything","to protect priceless works of art","from ruin."],"k":["제2차 세계대전 동안","한 무리의 사람들이 있었다","모든 것을 걸고","대단히 귀중한 예술 작품들을 지키기 위해","파괴로부터"]}]},{"ko":"1943년에, 14개의 다른 연합국에서 온 약 345명의 사람들이 기념물, 미술품, 그리고 기록물 (MFAA) 프로그램을 만들기 위해 모였다.","en":"In 1943, around 345 people from 14 different Allied nations ___[come] together ___[form] the Monuments, Fine Arts, and Archives (MFAA) program.","ans":["came","to form"],"part":0,"why":["1943년의 과거 일이라 come(오다)의 과거형 came(왔다)","‘~하기 위해’(목적)를 뜻하는 부사적 용법의 to부정사"],"jj":[{"e":["In 1943, around 345 people","from 14 different Allied nations","came together","to form the Monuments, Fine Arts, and Archives (MFAA) program."],"k":["1943년에 약 345명의 사람들이","14개의 서로 다른 연합국에서","함께 모였다","기념물, 미술품, 그리고 기록물 (MFAA) 프로그램을 만들기 위해"]}]},{"ko":"그들은 훈련된 군인이 아니라 교수, 역사학자, 건축가와 같은 다양한 분야의 학자들과 전문가들이었다.","en":"They ___[be] not ___[train] soldiers but scholars and experts of various kinds, such as professors, historians, and architects.","ans":["were","trained"],"part":0,"why":["주어 They(그들)가 복수이고 과거 이야기라서 were(~이었다)","soldiers(군인들)가 ‘훈련된’ 대상이라 수동의 뜻인 과거분사가 앞에서 꾸밈 [분사형 형용사]"],"jj":[{"e":["They were not trained soldiers","but scholars and experts of various kinds,","such as professors, historians, and architects."],"k":["그들은 훈련된 군인이 아니라","다양한 분야의 학자들과 전문가들이었다","교수, 역사학자, 건축가와 같은"]}]},{"ko":"이러한 용감한 남성과 여성은 유럽의 문화유산을 보호하는 일을 자청했고 '모뉴먼츠 맨'으로 알려지게 되었다.","en":"These brave men and women ___[volunteer] ___[protect] Europe’s cultural heritage and ___[become] ___[know] as the “Monuments Men.”","ans":["volunteered","to protect","became","known"],"part":0,"why":["과거 이야기이고 and(그리고)로 became(되었다)과 나란히 연결된 과거형 [병렬연결]","volunteer(자청하다)는 to부정사를 목적어로 취하는 동사 [volunteer+to부정사]","and(그리고)로 volunteered(자청했다)와 연결된 과거형, become(되다)의 과거형 became(되었다)","‘~로 알려진’이라는 수동의 뜻이라 과거분사 known(알려진)"],"jj":[{"e":["These brave men and women","volunteered","to protect Europe’s cultural heritage","and became known as the “Monuments Men.”"],"k":["이러한 용감한 남성과 여성은","자청했다","유럽의 문화유산을 보호하는 일을","그리고 “모뉴먼츠 맨”으로 알려지게 되었다"]}]},{"ko":"파괴를 막는 것부터 보물을 구하는 것까지\nMFAA가 처음 만들어졌을 때, 그것의 주된 목표는 문화적 랜드마크의 파괴를 막는 것이었다.","en":"From ___[Prevent] Destruction to ___[Save] Treasures\nWhen the MFAA ___[first, form], its main goal ___[be] ___[prevent] the destruction of cultural landmarks.","ans":["Preventing","Saving","was first formed","was","to prevent"],"part":1,"why":["전치사 From(~로부터) 뒤에는 동명사(-ing)가 온다","전치사 to(~까지) 뒤에는 동명사(-ing)가 온다(From A to B(A에서 B까지) 구조)","MFAA(문화재 보호 조직)는 ‘만들어진’ 대상이라 수동태 was formed(만들어졌다)","주어 its main goal(주요 목표)이 단수이고 과거라서 was(~이었다)","be동사 뒤 보어 자리라서 ‘~하는 것’을 뜻하는 to부정사 [명사적 용법의 to부정사]"],"jj":[{"e":["From Preventing Destruction to Saving Treasures"],"k":["파괴를 막는 것부터 보물을 구하는 것까지"]},{"e":["When the MFAA was first formed,","its main goal was","to prevent the destruction of cultural landmarks."],"k":["MFAA가 처음 만들어졌을 때","그것의 (=MFAA의) 주된 목표는","문화적 랜드마크의 파괴를 막는 것이었다"]}]},{"ko":"모뉴먼츠 맨은 연합군이 박물관, 교회, 또는 다른 문화적으로 중요한 건물들이 있는 지역을 폭격하지 않도록 설득했다.","en":"The Monuments Men ___[persuade] the Allied forces not ___[bomb] areas with museums, churches, or other culturally significant buildings.","ans":["persuaded","to bomb"],"part":1,"why":["과거 이야기라 persuade(설득하다)의 과거형 [5형식]","persuade(설득하다)+목적어 뒤에 to부정사, 부정은 not to(~하지 않도록)"],"star":1,"jj":[{"e":["The Monuments Men persuaded the Allied forces","not to bomb areas","with museums, churches, or other culturally significant buildings."],"k":["모뉴먼츠 맨은 연합군을 설득했다","지역들을 폭격하지 않도록","박물관, 교회, 또는 다른 문화적으로 중요한 건물들이 있는"]}]},{"ko":"그들은 또한 훼손된 건축물과 예술 작품을 복원하고자 이미 파괴된 지역을 방문했다.","en":"They also ___[visit] areas that ___[have, already, destroy] ___[restore] ___[damage] architecture and works of art.","ans":["visited","had already been destroyed","to restore","damaged"],"part":1,"why":["과거 이야기라 visit(방문하다)의 과거형","방문한 때보다 먼저 ‘파괴된’ 일이라 과거완료 수동(had been p.p.) [과거완료 수동태]","‘~하기 위해’(목적)를 뜻하는 부사적 용법의 to부정사","architecture(건축물)가 ‘훼손된’ 대상이라 수동의 뜻인 과거분사가 앞에서 꾸밈 [분사형 형용사 & 병렬연결]"],"star":1,"jj":[{"e":["They also visited areas","that had already been destroyed","to restore damaged architecture and works of art."],"k":["그들은 또한 지역들을 방문했다","이미 파괴된","훼손된 건축물과 예술 작품을 복원하기 위해"]}]},{"ko":"머지않아 그들의 역할은 확대되었다.","en":"It ___[be, not] long before their role ___[expand].","ans":["wasn’t","expanded"],"part":1,"why":["It wasn’t long before(~하기 전에) 구문, 과거라 be동사 과거 부정형 [it is not long before ~]","before(~하기 전에) 뒤 절도 과거 이야기라 과거형"],"jj":[{"e":["It wasn’t long","before their role expanded."],"k":["오래 걸리지 않았다","그들의 역할이 확대되기까지는"]}]},{"ko":"전쟁 중에, 나치는 유럽 전역의 나라들로부터 예술 작품들과 기타 문화재들을 훔치고 있었다.","en":"During the war, the Nazis ___[have, steal] works of art and other cultural treasures from countries across Europe.","ans":["had been stealing"],"part":1,"why":["과거 시점 전부터 계속된 일이라 과거완료진행(had been -ing) [과거완료 진행형]"],"jj":[{"e":["During the war,","the Nazis had been stealing works of art","and other cultural treasures","from countries across Europe."],"k":["전쟁 중에","나치는 예술 작품들을 훔치고 있었다","그리고 다른 문화재들을","유럽 전역의 나라들로부터"]}]},{"ko":"그들은 이러한 보물들을 성, 광산, 동굴 같은 곳에 숨겼다.","en":"They ___[hide] these treasures in places like castles, mines, and caves.","ans":["hid"],"part":1,"why":["과거 이야기이고 hide(숨기다)의 과거형은 hid(숨겼다)"],"jj":[{"e":["They hid these treasures","in places","like castles, mines, and caves."],"k":["그들은 이러한 보물들(=훔친 문화재들)을 숨겼다","장소들에","성, 광산, 동굴 같은"]}]},{"ko":"모뉴먼츠 맨이 이에 대해 알게 되었을 때, 그들은 도난당한 보물들을 찾기 시작했다.","en":"When the Monuments Men ___[learn] about this, they ___[start] ___[look] for the ___[steal] treasures.","ans":["learned","started","looking","stolen"],"part":1,"why":["시간 접속사 When(~할 때)절도 과거 이야기라 과거형 [접속사 when]","과거 이야기라 start(시작하다)의 과거형","start(시작하다)는 동명사나 to부정사를 목적어로 취해 looking(찾기) [start+동명사/to부정사]","treasures(보물)가 ‘도난당한’ 대상이라 수동의 뜻인 과거분사가 앞에서 꾸밈"],"jj":[{"e":["When the Monuments Men learned about this,","they started looking for the stolen treasures."],"k":["모뉴먼츠 맨이 이것(=나치가 보물을 숨긴 일)에 대해 알게 되었을 때","그들은 도난당한 보물들을 찾기 시작했다"]}]},{"ko":"그 후 그들의 수색은 '역사상 가장 위대한 보물찾기'라고 불려 왔다.","en":"Their search ___[have, since, call] “the greatest treasure hunt in history.”","ans":["has since been called"],"part":1,"why":["그 후 지금까지 이어지고 수동이라 현재완료 수동(has been p.p.) [현재완료 수동태]"],"star":1,"jj":[{"e":["Their search has since been called","“the greatest treasure hunt in history.”"],"k":["그들의 수색은 그 후 불려 왔다","“역사상 가장 위대한 보물찾기”라고"]}]},{"ko":"독일이 전쟁에서 패하기 시작했을 때, 도난당한 물건들은 위협을 받았다.","en":"When Germany ___[begin] ___[lose] the war, the ___[steal] objects ___[come] under threat.","ans":["began","to lose","stolen","came"],"part":1,"why":["when(~할 때)절의 과거 이야기라 과거형 began(시작했다)을 써요. [접속사 when]","begin(시작하다) 뒤에는 to부정사(또는 -ing)가 와서 to lose(패하다)를 써요. [begin+동명사/to부정사]","물건이 ‘도난당한’ 것이라 수동 뜻의 과거분사 stolen(도난당한)이 꾸며요.","과거 이야기라 come(오다)의 과거형 came(왔다)을 써요. come under threat(위협을 받다)이에요."],"jj":[{"e":["When Germany began to lose the war,","the stolen objects came under threat."],"k":["독일이 전쟁에서 패하기 시작했을 때","도난당한 물건들은 위협을 받았다"]}]},{"ko":"히틀러는 그의 군대에게 그들이 한 지역에서 후퇴하기 전에 연합군에게 유용할 수 있는 모든 것을 파괴하라고 명령했다.","en":"Hitler ___[order] his forces ___[destroy] everything that could ___[be] useful to the Allied armies before they ___[retreat] from an area.","ans":["ordered","to destroy","be","retreated"],"part":1,"why":["과거 이야기라 order(명령하다)의 과거형 ordered(명령했다)를 써요.","order(명령하다)+목적어 뒤에는 to부정사가 와서 to destroy(파괴하다)를 써요. [5형식]","조동사 could(~일 수 있다) 뒤에는 항상 동사원형 be(이다)가 와요.","before(~하기 전에)가 이끄는 절도 과거 이야기라 과거형 retreated(후퇴했다)를 써요. [접속사 before]"],"star":1,"jj":[{"e":["Hitler ordered his forces","to destroy everything","that could be useful to the Allied armies","before they retreated from an area."],"k":["히틀러는 그의 군대에게 명령했다","모든 것을 파괴하라고","연합군에게 유용할 수 있는","그들(=독일군)이 한 지역에서 후퇴하기 전에"]}]},{"ko":"일부 나치 지도자들은 이것이 군사 및 산업 장비뿐만 아니라 가치 있는 모든 것, 심지어 훔친 예술 작품들까지 포함한다고 여겼다.","en":"Some Nazi leaders ___[believe] that this ___[include] not just military and industrial equipment but everything of value—even the ___[steal] works of art.","ans":["believed","included","stolen"],"part":1,"why":["과거 이야기라 과거형 believed(여겼다)를 쓰고, 뒤에 that(~라는)절이 와요. [접속사 that]","that(~라는)절 안도 과거 시점이라 include(포함하다)의 과거형 included(포함했다)를 써요.","작품이 ‘도난당한’ 수동 관계라 과거분사 stolen(도난당한)이 앞에서 꾸며요. [분사형 형용사]"],"jj":[{"e":["Some Nazi leaders believed","that this included","not just military and industrial equipment","but everything of value","— even the stolen works of art."],"k":["일부 나치 지도자들은 여겼다","이것(=유용한 모든 것)이 포함한다고","군사 및 산업 장비뿐만 아니라","가치 있는 모든 것도","— 심지어 훔친 예술 작품들까지"]}]},{"ko":"도난당한 물품의 가장 큰 더미 중 하나는 오스트리아의 알타우제 소금 광산에 숨겨져 있었다.","en":"One of the largest collections of ___[steal] items ___[hide] in the salt mines of Altaussee, Austria.","ans":["stolen","was hidden"],"part":2,"why":["items(물품)가 ‘도난당한’ 수동 관계라 과거분사 stolen(도난당한)이 꾸며요. [one of the+최상급+복수명사(구) & 과거분사형 형용사 & 수일치]","주어 One(하나)이 ‘숨겨진’ 대상이라 수동태, 단수라 was(~였다) hidden(숨겨진)이에요."],"star":1,"jj":[{"e":["One of the largest collections of stolen items","was hidden","in the salt mines of Altaussee, Austria."],"k":["도난당한 물품들의 가장 큰 더미 중 하나는","숨겨져 있었다","오스트리아 알타우제의 소금 광산에"]}]},{"ko":"그것의 위치를 알아내자마자, 모뉴먼츠 맨 중 일부가 광산으로 급히 움직였다.","en":"Upon ___[discover] its location, some of the Monuments Men ___[rush] to the mines.","ans":["discovering","rushed"],"part":2,"why":["전치사 Upon(~하자마자) 뒤에는 동명사 discovering(알아내기)이 와요. [전치사의 목적어]","과거 이야기라 rush(급히 움직이다)의 과거형 rushed(급히 움직였다)를 써요."],"jj":[{"e":["Upon discovering its location,","some of the Monuments Men","rushed to the mines."],"k":["그것의(=그 더미의) 위치를 알아내자마자","모뉴먼츠 맨 중 일부가","광산으로 급히 움직였다"]}]},{"ko":"그들은 너무 늦기 전에 모든 것을 되찾기를 희망했다.","en":"They ___[hope] ___[recover] everything before it ___[be] too late.","ans":["hoped","to recover","was"],"part":2,"why":["과거 이야기라 hope(희망하다)의 과거형 hoped(희망했다)를 써요. [hope+to부정사]","hope(희망하다)는 to부정사를 목적어로 써서 to recover(되찾다)가 돼요.","before(~하기 전에)절의 과거 이야기이고 주어 it(그것)이 단수라 was(~였다)예요. [접속사 before & 비인칭주어 it]"],"jj":[{"e":["They hoped","to recover everything","before it was too late."],"k":["그들은 희망했다","모든 것을 되찾기를","너무 늦기 전에"]}]},{"ko":"한편, 그 지역을 담당하던 나치 지도자는 광산 내부에 대형 폭발물을 터뜨려 모든 것을 파괴하려고 했다.","en":"Meanwhile, the Nazi leader who ___[be] in charge of the area ___[try] ___[destroy] everything by ___[set] off large explosives inside the mines.","ans":["was","tried","to destroy","setting"],"part":2,"why":["who(~하는) 뒤 동사는 선행사 the Nazi leader(나치 지도자)에 맞춘 과거형 was(~였다)예요. [주격 관계대명사]","과거 이야기라 try(노력하다)의 과거형 tried(하려고 했다)를 써요.","try(노력하다) 뒤에 to부정사가 오면 ‘~하려고 노력하다’라서 to destroy(파괴하다)예요. [try+to부정사]","전치사 by(~함으로써) 뒤에는 동명사 setting(터뜨리기)이 와요. [by+-ing]"],"jj":[{"e":["Meanwhile, the Nazi leader","who was in charge of the area","tried to destroy everything","by setting off large explosives","inside the mines."],"k":["한편 그 나치 지도자는","그 지역을 담당하던","모든 것을 파괴하려고 했다","대형 폭발물을 터뜨려서","광산 내부에"]}]},{"ko":"이는 처참할 수 있었다.","en":"This could ___[have, be] disastrous.","ans":["have been"],"part":2,"why":["could have(~했을 수도 있다)+과거분사는 과거 추측이라 have been(~였다)을 써요. [조동사+have+p.p.]"],"star":1,"jj":[{"e":["This could have been disastrous."],"k":["이것은(=폭발물을 터뜨리려던 시도는) 처참할 수 있었다"]}]},{"ko":"다행히도, 지역의 일부 광부들이 광산에서 폭발물을 발견했고 자신들의 생계를 보호할 계획을 생각해 냈다.","en":"Luckily, some local miners ___[find] the explosives in the mines and ___[come] up with a plan ___[protect] their livelihood.","ans":["found","came","to protect"],"part":2,"why":["and(그리고)로 이어진 병렬 구조라 find(발견하다)의 과거형 found(발견했다)를 써요. [병렬연결]","found(발견했다)와 병렬이라 과거형 came(왔다)이에요. come up with(생각해 내다)예요.","명사 a plan(계획)을 뒤에서 꾸미는 to부정사라서 to protect(보호하다)예요. [형용사적 용법의 to부정사]"],"jj":[{"e":["Luckily, some local miners found the explosives","in the mines","and came up with a plan","to protect their livelihood."],"k":["다행히 지역의 일부 광부들이 폭발물을 발견했다","광산에서","그리고 계획을 생각해 냈다","자신들의 생계를 보호할"]}]},{"ko":"그들은 몰래 대형 폭발물을 제거했고 입구에 더 작은 폭발물을 놓았다.","en":"They secretly ___[remove] the large explosives and ___[put] smaller ones at the entrances.","ans":["removed","put"],"part":2,"why":["and(그리고)로 이어진 병렬 과거동사라 과거형 removed(제거했다)를 써요. [병렬연결]","put(놓다)은 현재·과거 모양이 같아요. removed(제거했다)와 병렬이라 과거예요."],"jj":[{"e":["They secretly removed the large explosives","and put smaller ones","at the entrances."],"k":["그들은 몰래 대형 폭발물을 제거했다","그리고 더 작은 것들(=폭발물들)을 놓았다","입구에"]}]},{"ko":"그것들이 터지자, 나치 지도자는 모든 것이 파괴되었다고 여겼다.","en":"Once they ___[go] off, the Nazi leader ___[believe] that everything ___[destroy].","ans":["went","believed","was destroyed"],"part":2,"why":["Once(~하자)절의 과거 이야기라 go off(터지다)의 과거형 went(갔다)를 써요. [접속사 once]","과거 이야기라 과거형 believed(여겼다)를 쓰고, 뒤에 that(~라는)절이 와요. [접속사 that]","everything(모든 것)이 ‘파괴된’ 대상이라 수동태, 단수라 was(~였다) destroyed(파괴된)예요. [수동태 & 수일치]"],"jj":[{"e":["Once they went off,","the Nazi leader believed","that everything was destroyed."],"k":["그것들(=작은 폭발물들)이 터지자","나치 지도자는 여겼다","모든 것이 파괴되었다고"]}]},{"ko":"그러나 작은 폭발들이 입구를 봉쇄시키긴 했지만, 그것들은 광산의 나머지 부분과 예술 작품들을 손상되지 않은 채로 남아 있게 했다.","en":"However, while the small explosions ___[seal] off the entrances, they ___[leave] the rest of the mines and the works of art unharmed.","ans":["sealed","left"],"part":2,"why":["while(~하는 동안)절의 과거 이야기라 seal off(봉쇄하다)의 과거형 sealed(봉쇄했다)를 써요. [접속사 while]","leave(두다)+목적어+형용사는 ‘~한 채로 두다’이고, 과거라 left(두었다)예요. [5형식 & 과거분사형 형용사]"],"jj":[{"e":["However, while the small explosions sealed off the entrances,","they left the rest of the mines","and the works of art","unharmed."],"k":["그러나 작은 폭발들이 입구를 봉쇄시켰지만","그것들(=작은 폭발들)은 광산의 나머지 부분을","그리고 예술 작품들을","손상되지 않은 채로 남아 있게 했다"]}]},{"ko":"모뉴먼츠 맨이 도착해 광산 안으로 비집고 들어갔을 때, 그들은 내부에 있던 것을 보고 놀랐음에 틀림없다.","en":"When the Monuments Men ___[arrive] and ___[squeeze] their way into the mines, they must ___[have, amaze] ___[see] what ___[be] inside.","ans":["arrived","squeezed","have been amazed","to see","was"],"part":2,"why":["when(~할 때)절의 일이 과거에 일어났으므로 과거형이에요. [접속사 when / 병렬연결]","and(그리고)로 arrived(도착했다)와 나란히 이어진 과거 동작이라 과거형이에요.","must have+p.p.(~했음이 틀림없다)는 과거 추측이고, 놀라움을 느낀 쪽이라 amazed(놀란)예요. [조동사+have+p.p. & 감정 형용사]","놀란 이유(감정의 원인)를 나타내는 to부정사예요. [부사적 용법의 to부정사]","what(~것) 절 안의 동사이고 과거 이야기라서 과거형 was(~이었다)예요. [관계대명사 what]"],"star":1,"jj":[{"e":["When the Monuments Men arrived","and squeezed their way into the mines,","they must have been amazed","to see what was inside."],"k":["모뉴먼츠 맨이 도착했을 때","그리고 광산 안으로 비집고 들어갔을 때","그들은 놀랐음에 틀림없다","안에 있던 것을 보고"]}]},{"ko":"그곳에는 그림, 조각상, 책, 가구 등을 포함해 수천 점의 귀중한 물건들이 있었다.","en":"There ___[be] thousands of priceless objects, including paintings, statues, books, furniture, and more.","ans":["were"],"part":2,"why":["주어 objects(물건들)가 복수라서 were(~이 있었다)예요. [유도부사 구문]"],"jj":[{"e":["There were thousands of priceless objects,","including paintings, statues, books, furniture, and more."],"k":["그곳에는 수천 점의 귀중한 물건들이 있었다","그림, 조각상, 책, 가구 등을 포함해"]}]},{"ko":"모뉴먼츠 맨은 그들이 발견한 모든 것을 안전한 장소로 옮기는 데 대략 1년이 걸릴 것으로 생각했다.","en":"The Monuments Men ___[think] it would ___[take] about one year ___[transport] everything they ___[find] to a safe location.","ans":["thought","take","to transport","found"],"part":3,"why":["과거 이야기이므로 think(생각하다)의 과거형 thought(생각했다)예요. [명사절 접속사 that의 생략]","조동사 would(~할 것이다) 뒤에는 동사원형을 써요. [it+takes+시간+to부정사]","가주어 it(그것)의 진짜 주어로 쓰인 to부정사예요.","everything(모든 것)을 꾸미는 관계절 속 동사이고, 과거에 한 일이라 found(발견했다)예요. [목적격 관계대명사의 생략]"],"jj":[{"e":["The Monuments Men thought","it would take about one year","to transport everything they found","to a safe location."],"k":["모뉴먼츠 맨은 생각했다","(가주어) 대략 1년이 걸릴 것이라고","그들이 발견한 모든 것을 옮기는 데","안전한 장소로"]}]},{"ko":"그러나 전쟁이 끝날 때 그 지역의 통제권이 바뀔 예정이었기 때문에, 그들은 오직 두 달 동안만 광산에 접근하게 될 것이었다.","en":"However, because control of the area ___[be] going ___[change] at the end of the war, they would ___[have] access to the mines for just two months.","ans":["was","to change","have"],"part":3,"why":["주어 control(통제권)이 단수이고 과거 이야기라서 was(~이었다)예요. [접속사 because / be going to+동사원형]","be going to(~할 예정이다) 구조라서 뒤에 동사원형 change(바뀌다)가 와요.","조동사 would(~할 것이다) 뒤에는 동사원형 have(가지다)를 써요."],"jj":[{"e":["However, because control of the area","was going to change","at the end of the war,","they would have access to the mines","for just two months."],"k":["그러나 그 지역의 통제권이","바뀔 예정이었기 때문에","전쟁이 끝날 때","그들은 광산에 접근하게 될 것이었다","오직 두 달 동안만"]}]},{"ko":"불충분한 포장 자재와 오직 몇 대의 트럭으로 수송 임무는 불가능한 것처럼 보였다.","en":"With insufficient packing supplies and only a few trucks, the ___[transport] mission ___[seem] impossible.","ans":["transporting","seemed"],"part":3,"why":["명사 mission(임무) 앞에서 ‘수송용’의 뜻을 더하는 -ing 형태예요.","과거 이야기이고 seem(~처럼 보이다) 뒤에는 형용사가 와요. [seem+형용사]"],"jj":[{"e":["With insufficient packing supplies and only a few trucks,","the transporting mission seemed impossible."],"k":["불충분한 포장 자재와 오직 몇 대의 트럭으로","수송 임무는 불가능한 것처럼 보였다"]}]},{"ko":"그뿐만 아니라 식량 공급량도 부족했다.","en":"Not only that, but food ___[be] in short supply.","ans":["was"],"part":3,"why":["주어 food(식량)가 단수이고 과거 이야기라서 was(~이었다)예요."],"jj":[{"e":["Not only that, but food was in short supply."],"k":["그것(=자재와 트럭 부족)뿐만 아니라 식량 공급량도 부족했다"]}]},{"ko":"제대로 된 식사도 하지 못한 채, 그들은 하루에 20시간까지 일했다.","en":"Even without ___[eat] proper meals, they ___[work] up to twenty hours a day.","ans":["eating","worked"],"part":3,"why":["전치사 without(~없이) 뒤에는 동명사(-ing)가 와요. [전치사의 목적어]","과거에 한 일이라 과거형 worked(일했다)예요."],"jj":[{"e":["Even without eating proper meals,","they worked up to twenty hours a day."],"k":["제대로 된 식사도 하지 못한 채","그들은 하루에 20시간까지 일했다"]}]},{"ko":"그들은 외투와 방독면을 포장 재료로 사용했고 이 중요한 임무를 시간 내에 완수하기 위해 그들이 할 수 있는 모든 것을 했다.","en":"They ___[use] coats and gas masks as packing materials and ___[do] everything they could ___[accomplish] this vital mission in time.","ans":["used","did","to accomplish"],"part":3,"why":["주어 They(그들)의 과거 행동이고 and(그리고)로 did(했다)와 나란히 이어져요. [병렬연결]","and(그리고) 뒤에 used(사용했다)와 나란히 쓰인 과거동사예요.","‘~하기 위해’라는 목적을 나타내는 to부정사예요. [부사적 용법의 to부정사]"],"jj":[{"e":["They used coats and gas masks as packing materials","and did everything they could","to accomplish this vital mission in time."],"k":["그들은 외투와 방독면을 포장 재료로 사용했다","그리고 할 수 있는 모든 것을 했다","이 중요한 임무(=수송 임무)를 시간 내에 완수하기 위해"]}]},{"ko":"마침내, 모뉴먼츠 맨은 얀 반 에이크의 「신비한 어린 양에 대한 경배」, 요하네스 페르메이르의 「천문학자」, 그리고 미켈란젤로의 「브뤼헤의 성모」와 같은 중요한 작품들을 포함하여 수천 점의 도난당한 예술 작품을 구출하는 데 성공했다.","en":"In the end, the Monuments Men ___[succeed] in rescuing thousands of ___[steal] works of art, including important pieces such as Jan van Eyck’s Adoration of the Mystic Lamb, Johannes Vermeer’s The Astronomer, and Michelangelo’s Madonna of Bruges.","ans":["succeeded","stolen"],"part":3,"why":["과거 이야기라 succeed(성공하다)의 과거형 succeeded(성공했다)이고, 뒤에는 in(~에)+동명사가 이어져요. [구동사 succeed in ~ & 전치사의 목적어]","works of art(예술 작품)가 도난당한 대상이라 과거분사 stolen(도난당한)이에요. [분사형 형용사]"],"jj":[{"e":["In the end, the Monuments Men succeeded in rescuing","thousands of stolen works of art,","including important pieces","such as Jan van Eyck’s Adoration of the Mystic Lamb,","Johannes Vermeer’s The Astronomer,","and Michelangelo’s Madonna of Bruges."],"k":["마침내 모뉴먼츠 맨은 구출하는 데 성공했다","수천 점의 도난당한 예술 작품을","중요한 작품들을 포함해","얀 반 에이크의 「신비한 어린 양에 대한 경배」","요하네스 페르메이르의 「천문학자」","그리고 미켈란젤로의 「브뤼헤의 성모」와 같은"]}]},{"ko":"모뉴먼츠 맨의 지속적인 영향\n모뉴먼츠 맨의 노력은 전쟁과 함께 끝나지 않았다.","en":"The ___[Continue] Impact of the Monuments Men\nThe efforts of the Monuments Men ___[not, end] with the war.","ans":["Continuing","did not end"],"part":4,"why":["명사 Impact(영향)를 꾸미는 -ing 형용사로 ‘계속되는’이에요.","did not(~하지 않았다) 다음에는 동사원형 end(끝나다)를 써요."],"jj":[{"e":["The Continuing Impact of the Monuments Men"],"k":["모뉴먼츠 맨의 지속적인 영향"]},{"e":["The efforts of the Monuments Men","did not end with the war."],"k":["모뉴먼츠 맨의 노력은","전쟁과 함께 끝나지 않았다"]}]},{"ko":"여러 해 동안, 그들은 문화재를 되찾고 그것들이 어디에서 도난당했는지 식별하는 작업을 이어갔다.","en":"For several years, they ___[continue] the work of ___[recover] cultural treasures and ___[identify] where they ___[have, steal] from.","ans":["continued","recovering","identifying","had been stolen"],"part":4,"why":["For several years(여러 해 동안)가 과거 이야기라 과거형이에요.","전치사 of(~의) 뒤에 동명사가 오고 and(그리고)로 identifying(식별하는 것)과 나란해요. [전치사의 목적어 & 병렬연결]","전치사 of(~의) 뒤 동명사이고 recovering(되찾는 것)과 병렬 연결돼요.","도난당한 일이 continued(이어갔다)보다 앞서서 과거완료 수동태예요. [간접의문문]"],"star":1,"jj":[{"e":["For several years,","they continued the work","of recovering cultural treasures","and identifying where they had been stolen from."],"k":["여러 해 동안","그들은 작업을 이어갔다","문화재를 되찾는","그리고 그것들(=문화재들)이 어디에서 도난당했는지 식별하는"]}]},{"ko":"마침내, 모뉴먼츠 맨은 5백만 점이 넘는 예술 작품과 문화적으로 중요한 물건들을 그것들의 원래 장소들로 돌려보냈다.","en":"In the end, the Monuments Men ___[return] more than five million works of art and objects of cultural importance to their places of origin.","ans":["returned"],"part":4,"why":["과거에 한 일이라 과거형 returned(돌려보냈다)예요."],"jj":[{"e":["In the end, the Monuments Men returned","more than five million works of art","and objects of cultural importance","to their places of origin."],"k":["마침내 모뉴먼츠 맨은 돌려보냈다","5백만 점이 넘는 예술 작품을","그리고 문화적으로 중요한 물건들을","그것들의(=예술 작품과 물건들의) 원래 장소로"]}]},{"ko":"나치에 의해 도난당한 모든 것이 발견되지는 않았지만, 모뉴먼츠 맨이 이룬 것은 정말로 놀랍다.","en":"Not everything that ___[steal] by the Nazis ___[have, find], but what the Monuments Men ___[accomplish] ___[truly, amaze].","ans":["was stolen","has been found","accomplished","is truly amazing"],"part":4,"why":["everything(모든 것)이 도난당한 대상이라 과거 수동태 was(~되었다) stolen(도난당한)","everything(모든 것)이 발견된 대상이라 현재완료 수동태 has been found(발견되었다)","what(~하는 것)절 안의 동사라 과거형 accomplished(이루었다)이고, 목적어는 what이 대신함 [관계대명사 what]","주어가 놀라움을 주는 쪽이라 능동의 amazing(놀라운)을 씀 [감정 형용사]"],"star":1,"jj":[{"e":["Not everything","that was stolen by the Nazis","has been found,","but what the Monuments Men accomplished","is truly amazing."],"k":["모든 것이","나치에 의해 도난당한","발견된 것은 아니지만","모뉴먼츠 맨이 이룬 것은","정말로 놀랍다"]}]},{"ko":"이 결연한 집단이 없었다면, 도난당한 예술 작품들의 수색은 시작되지 않았을지도 모른다.","en":"Without this determined group, the search for stolen works of art might never ___[have, begin].","ans":["have begun"],"part":4,"why":["might(~일지도 모른다) never(결코 ~않다) have + p.p.는 ‘~하지 않았을지도 모른다’(과거 가정) [가정법 과거완료]"],"star":1,"jj":[{"e":["Without this determined group,","the search for stolen works of art","might never have begun."],"k":["이 결연한 집단(=모뉴먼츠 맨)이 없었다면","도난당한 예술 작품들의 수색은","시작되지 않았을지도 모른다"]}]},{"ko":"또한, 수많은 역사적, 문화적 랜드마크가 전쟁의 파괴로 인해 영원히 사라져 버렸을 것이다.","en":"In addition, countless historical and cultural landmarks would ___[have, lose] forever due to the destruction of war.","ans":["have been lost"],"part":4,"why":["would(~했을 것이다) have been + p.p.는 ‘~되었을 것이다’(과거 가정의 수동) [가정법 과거완료 수동태]"],"star":1,"jj":[{"e":["In addition, countless historical and cultural landmarks","would have been lost forever","due to the destruction of war."],"k":["또한 수많은 역사적, 문화적 랜드마크가","영원히 사라져 버렸을 것이다","전쟁의 파괴로 인해"]}]},{"ko":"문화유산 보존에 대한 모뉴먼츠 맨의 기여는 기억할 가치가 있다.","en":"It ___[be] worth ___[remember] the Monuments Men’s contribution to the preservation of cultural heritage.","ans":["is","remembering"],"part":4,"why":["가주어 It(그것)이 단수 주어라 be동사 현재형 is(이다) [가주어-진주어 구문]","worth(~할 가치가 있는) 뒤에는 동명사(-ing)가 와서 ‘~할 가치가 있다’"],"jj":[{"e":["It is worth remembering","the Monuments Men’s contribution","to the preservation of cultural heritage."],"k":["(가주어) 기억할 가치가 있다","모뉴먼츠 맨의 기여를","문화유산 보존에 대한"]}]},{"ko":"그들의 노력 덕분에, 많은 놀라운 문화 유적지들과 예술 작품들이 살아남아 오늘날까지도 여전히 감상될 수 있다.","en":"Thanks to their efforts, many incredible cultural sites and works of art ___[have, survive] and can still ___[appreciate] to this day.","ans":["have survived","be appreciated"],"part":4,"why":["과거부터 이어진 결과를 나타내는 현재완료 have + p.p.","can(~할 수 있다) 뒤에는 be + p.p.: 작품이 감상되는 수동 관계 [병렬연결]"],"jj":[{"e":["Thanks to their efforts,","many incredible cultural sites and works of art","have survived","and can still be appreciated","to this day."],"k":["그들의 노력 덕분에","많은 놀라운 문화 유적지들과 예술 작품들이","살아남았다","그리고 여전히 감상될 수 있다","오늘날까지"]}]},{"ko":"당신의 언어를 잃지 마라!\n당신은 현재 전 세계에서 7,000개가 넘는 언어가 사용되고 있다는 것을 알고 있었는가?","en":"Culture Notes: ___[Not, Lose] Your Language!\n___[Do] you ___[know] that there ___[be] over 7,000 languages currently ___[use] around the world?","ans":["Don’t Lose","Did","know","are","being used"],"part":5,"why":["‘~하지 마라’는 Don’t(~하지 마라) + 동사원형 Lose(잃다)인 명령문","과거 시제 의문문이라 Did(~했는가)로 시작하고 과거 표시는 Did가 함","Did(~했는가) 뒤에는 동사원형 know(알다)를 쓰고, that(~라는 것)절이 목적어임 [접속사 that]","there(~이 있다) 뒤 주어가 복수(languages(언어들))라 복수동사 are(있다) [유도부사 구문]","languages(언어들)가 사용되는 대상이라 진행 수동 being used(사용되는 중인) [현재분사의 수동형]"],"jj":[{"e":["Culture Notes: Don’t Lose Your Language!"],"k":["당신의 언어를 잃지 마라!"]},{"e":["Did you know","that there are over 7,000 languages","currently being used","around the world?"],"k":["당신은 알고 있었는가","7,000개가 넘는 언어가 있다는 것을","현재 사용되고 있는","전 세계에서"]}]},{"ko":"이러한 언어들의 대부분은 매우 소규모 집단의 사람들에 의해 사용되며, 그중 절반은 다음 세대 이내에 사라질 수도 있다.","en":"Most of these languages ___[speak] by very small groups of people, and half of them could ___[disappear] within the next generation.","ans":["are spoken","disappear"],"part":5,"why":["Most of these languages(이 언어들 대부분)가 말해지는 대상이라 복수 수동태 are(~이다) spoken(말해진) [most of ~ & 수일치]","조동사 could(~할 수 있다) 뒤에는 동사원형 disappear(사라지다)를 씀"],"jj":[{"e":["Most of these languages are spoken","by very small groups of people,","and half of them could disappear","within the next generation."],"k":["이러한 언어들의 대부분은 사용된다","매우 소규모 집단의 사람들에 의해","그리고 그중(=그 언어들 중) 절반은 사라질 수도 있다","다음 세대 이내에"]}]},{"ko":"이는 큰 손실이 될 텐데 언어가 사람들의 정체성을 그들의 문화와 연결하는 데 큰 역할을 하기 때문이다.","en":"This would ___[be] a great loss because language ___[play] a big role in ___[connect] people’s identity to their culture.","ans":["be","plays","connecting"],"part":5,"why":["조동사 would(~일 것이다) 뒤에는 동사원형 be를 씀","because(~때문에)절의 주어 language(언어)가 단수라 plays(맡다) [접속사 because]","전치사 in(~하는 데) 뒤에는 동명사(-ing)가 온다 [전치사의 목적어]"],"jj":[{"e":["This would be a great loss","because language plays a big role","in connecting people’s identity to their culture."],"k":["이것은(=그 언어들 중 절반이 사라질 수도 있다는 것은) 큰 손실이 될 것이다","언어가 큰 역할을 하기 때문에","사람들의 정체성을 그들의 문화와 연결하는 데"]}]},{"ko":"이것이 일부 단체가 언어를 보존하기 위해 일하는 이유이다.","en":"This ___[be] why some organizations ___[work] ___[preserve] them.","ans":["is","work","to preserve"],"part":5,"why":["주어 This(이것)가 단수이고 현재 시제라 be동사 is(이다) [명사절을 이끄는 관계부사 why]","주어 some organizations(일부 단체)가 복수라 동사원형 work(노력하다)","‘~하기 위해’(목적)는 to + 동사원형 형태의 to부정사"],"jj":[{"e":["This is why","some organizations work","to preserve them."],"k":["이것이(=언어가 사라질 수 있다는 점이) 이유이다","일부 단체가 일하는","그것들(=언어들)을 보존하기 위해"]}]},{"ko":"예를 들어, Wikitongues라는 비영리 단체는 소멸될 위험에 처한 모든 언어들을 보존한다는 목표를 세웠다.","en":"For example, a nonprofit organization ___[call] Wikitongues ___[have, set] the goal of ___[preserve] all languages that ___[be] in danger of ___[lose].","ans":["called","has set","preserving","are","being lost"],"part":5,"why":["nonprofit organization(비영리 단체)이 ‘불리는’ 대상이라 과거분사 called(불리는) [명사를 수식하는 과거분사구]","결과를 나타내는 현재완료 has + p.p.(주어가 단수)","전치사 of(~의) 뒤에는 동명사(-ing)가 온다 [전치사의 목적어]","선행사 all languages(모든 언어)가 복수라 동사도 복수 are(있다) [주격 관계대명사]","언어가 사라지는 수동이라 전치사 of(~의) 뒤에 being + p.p. [전치사의 목적어 & 수동형 동명사]"],"star":1,"jj":[{"e":["For example, a nonprofit organization called Wikitongues","has set the goal","of preserving all languages","that are in danger of being lost."],"k":["예를 들어 Wikitongues라고 불리는 비영리 단체는","목표를 세웠다","모든 언어를 보존한다는","소멸될 위험에 처한"]}]},{"ko":"그 단체는 이 언어들을 사용하는 개인들의 영상을 기록하고 모국어 자원을 더 접근 가능하게 함으로써 이를 달성하기 위해 노력한다.","en":"The organization ___[work] ___[achieve] this by ___[record] videos of individuals ___[speak] these languages and ___[make] mother-tongue resources more accessible.","ans":["works","to achieve","recording","speaking","making"],"part":5,"why":["주어 The organization(단체)이 단수라 동사 works(노력하다)에 -s를 붙임","‘~하기 위해’(목적)를 나타내는 to부정사 [부사적 용법의 to부정사]","전치사 by(~함으로써) 뒤에는 동명사(-ing)를 쓴다 [by+-ing & 병렬연결]","individuals(개인들)가 말하는 주체라 능동의 현재분사 speaking(말하는) [명사를 수식하는 현재분사구]","by(~함으로써) 뒤에서 recording(기록하는 것)과 and(그리고)로 이어진 동명사 making(만드는 것) [5형식]"],"jj":[{"e":["The organization works to achieve this","by recording videos of individuals","speaking these languages","and making mother-tongue resources","more accessible."],"k":["그 단체는 이것(=이 목표)을 달성하기 위해 노력한다","개인들의 영상을 기록함으로써","이러한 언어들을 사용하는","그리고 모국어 자원을","더 접근 가능하게 만듦으로써"]}]}]},{"name":"4과","parts":[{"name":"❶","title":"웹을 모두에게 열어 두기 · Opening Up the Web to Everyone","n":11},{"name":"❷","title":"이미지에 대한 텍스트 설명 · Text Descriptions of Images","n":8},{"name":"❸","title":"멀티미디어 콘텐츠를 위한 대본과 자막 · Transcripts and Captions for Multimedia Content","n":6},{"name":"❹","title":"보고 듣기에 쉬운 콘텐츠 · Content That Is Easy to See and Hear","n":6},{"name":"❺","title":"키보드를 사용하는 완전한 탐색 · Complete Navigation Using the Keyboard","n":7},{"name":"❻","title":"정보를 전달하는 색상 이외의 지표들 · Indicators Other than Color That Convey Information","n":8},{"name":"❼","title":"웹을 더 문화적으로 접근 가능하게 만들기 · Making the Web More Culturally Accessible","n":6}],"items":[{"ko":"당신이 넘어져 당신의 오른팔이 부러졌다고 상상해 보라.","en":"___[Imagine] you ___[have, fall] down and ___[break] your right arm.","ans":["Imagine","have fallen","broken"],"part":0,"why":["주어 없이 동사원형 Imagine(상상해 보라)으로 시작하는 명령문이라 원형 그대로 써요.","‘넘어져서 지금 결과가 남은’ 현재완료라 have(~했다) 뒤에 과거분사 fallen(넘어진)이 와요. [현재완료 & 병렬연결]","have(~했다) 뒤에서 and(그리고)로 이어진 병렬이라 fallen(넘어진)과 같은 과거분사 broken(부러진)을 써요."],"jj":[{"e":["Imagine you have fallen down","and broken your right arm."],"k":["당신이 넘어졌다고 상상해 봐라","그리고 당신의 오른팔이 부러졌다고 상상해 봐라"]}]},{"ko":"당신의 다친 팔로 하기에 어려울 몇몇 일들이 있다.","en":"There ___[be] some things that ___[would, be] difficult ___[do] with your ___[injure] arm.","ans":["are","would be","to do","injured"],"part":0,"why":["There(~이 있다) 구문에서 뒤의 주어 some things(몇몇 일들)이 복수라 복수동사 are(이다)를 써요. [유도부사 구문]","조동사 would(~일 것이다) 뒤에는 동사원형 be(이다)를 써요.","difficult(어려운)를 꾸며 ‘~하기에’라는 뜻이라 to부정사 to do(하기에)를 써요. [부사적 용법의 to부정사]","arm(팔)이 ‘다치게 된’ 것이라 수동의 뜻인 과거분사 injured(다친)를 써요. [분사형 형용사]"],"jj":[{"e":["There are some things","that would be difficult to do","with your injured arm."],"k":["몇몇 일들이 있다","하기에 어려울","당신의 다친 팔로"]}]},{"ko":"예를 들어, 당신은 무거운 상자를 옮기거나 자전거를 타지 못할 수도 있다.","en":"For example, you ___[might, not, be] able ___[carry] heavy boxes or ___[ride] your bike.","ans":["might not be","to carry","ride"],"part":0,"why":["might(~일지도 모른다) 뒤에는 not be able(할 수 없다)처럼 동사원형 be가 와요. [be able+to부정사 & 병렬연결]","be(이다) able(할 수 있는) 뒤에는 to부정사 to carry(옮기는 것)를 써서 ‘~할 수 있는’이 돼요.","or(또는)로 이어진 병렬이고 앞의 to(~하기)를 공유해서 동사원형 ride(타다)만 써요."],"jj":[{"e":["For example, you might not be able to carry heavy boxes","or ride your bike."],"k":["예를 들어 당신은 무거운 상자를 옮길 수 없을지도 모른다","또는 자전거를 탈 수 없을지도 모른다"]}]},{"ko":"인터넷에 접속하는 것은 어떨까?","en":"What about ___[access] the Internet?","ans":["accessing"],"part":0,"why":["전치사 about(~에 대해) 뒤에는 동명사 accessing(접속하는 것)처럼 -ing를 써요. [What about+-ing~?]"],"jj":[{"e":["What about accessing the Internet?"],"k":["인터넷에 접속하는 것은 어떨까?"]}]},{"ko":"만약 당신이 오른손잡이라면, 당신의 왼손으로 컴퓨터 마우스나 터치스크린을 사용하는 것은 어색하고 많은 시간이 걸릴 것이다.","en":"If you ___[be] right-handed, ___[use] a computer mouse or touchscreen with your left hand ___[would, be] awkward and ___[take] a lot of time.","ans":["are","using","would be","take"],"part":0,"why":["If(만약)절의 주어가 you(당신)라서 be동사는 are(이다)예요.","문장의 주어 자리에는 ‘~하는 것’이 되는 동명사 using(사용하는 것)을 써요. [동명사구 주어]","조동사 would(~일 것이다) 뒤에는 동사원형 be(이다)를 써요. [병렬연결]","and(그리고)로 이어진 병렬이라 would(~일 것이다) 뒤에 be(이다)와 같은 동사원형 take(걸리다)를 써요."],"jj":[{"e":["If you are right-handed,","using a computer mouse or touchscreen","with your left hand","would be awkward","and take a lot of time."],"k":["만약 당신이 오른손잡이라면","컴퓨터 마우스나 터치스크린을 사용하는 것은","당신의 왼손으로","어색할 것이다","그리고 많은 시간이 걸릴 것이다"]}]},{"ko":"그러나 이것은 우리 중 몇몇이 인터넷에서 직면하는 것에 비해 작은 문제이다.","en":"However, this ___[be] a minor challenge ___[compare] to what some of us ___[face] on the Internet.","ans":["is","compared","face"],"part":0,"why":["주어 this(이것)가 단수이고 현재 시제라 is(이다)를 써요.","‘~에 비해’라는 뜻의 compared(비교된) to(~에) 표현에서는 과거분사를 써요. [compared to ~ & 관계대명사 what]","관계대명사 what(~것)절 안의 주어 some of us(우리 중 일부)가 복수라 동사원형 face(마주하다)를 써요."],"star":1,"jj":[{"e":["However, this is a minor challenge","compared to what some of us face","on the Internet."],"k":["그러나 이것은(=왼손으로 인터넷을 사용하는 것은) 작은 문제이다","우리 중 몇몇이 직면하는 것에 비해","인터넷에서"]}]},{"ko":"특정 장애가 있는 사람들에게는, 많은 웹 사이트가 사용하기에 거의 불가능할 수 있다.","en":"For people with certain disabilities, many websites ___[can, be] nearly impossible ___[use].","ans":["can be","to use"],"part":0,"why":["조동사 can(~할 수 있다) 뒤에는 동사원형 be(이다)를 써요.","impossible(불가능한)을 꾸며 ‘~하기에’라는 뜻이라 to부정사 to use(사용하기에)를 써요. [부사적 용법의 to부정사]"],"jj":[{"e":["For people with certain disabilities,","many websites can be nearly impossible to use."],"k":["특정 장애가 있는 사람들에게는","많은 웹 사이트가 사용하기에 거의 불가능할 수 있다"]}]},{"ko":"이것이 웹 접근성이 중요한 이유이다.","en":"This ___[be] the reason why web accessibility ___[be] important.","ans":["is","is"],"part":0,"why":["주어 This(이것)가 단수이고 현재 시제라 is(이다)를 써요.","관계부사 why(~한 이유) 뒤 절의 주어 web accessibility(웹 접근성)가 단수라 is(이다)를 써요."],"star":1,"jj":[{"e":["This is the reason","why web accessibility is important."],"k":["이것이(=많은 웹 사이트가 사용하기 거의 불가능하다는 것이) 이유이다","웹 접근성이 중요한 이유"]}]},{"ko":"웹 접근성은 웹 사이트가 장애가 있는 사람들을 포함하여 반드시 모두에게 사용될 수 있도록 하는 실천이다.","en":"Web accessibility ___[be] the practice of ___[make] sure that websites ___[can, use] by everyone, including people with disabilities.","ans":["is","making","can be used"],"part":0,"why":["주어 Web accessibility(웹 접근성)가 단수라 be동사는 is(이다)예요.","전치사 of(~의) 뒤에는 동명사 making(만드는 것)처럼 -ing를 써요. [전치사의 목적어 / make sure that ~]","websites(웹사이트)는 ‘사용되는’ 대상이라 수동태 can be used(사용될 수 있다)를 써요."],"jj":[{"e":["Web accessibility is the practice","of making sure","that websites can be used by everyone,","including people with disabilities."],"k":["웹 접근성은 실천이다","확실히 하는","웹 사이트가 모두에게 사용될 수 있도록","장애가 있는 사람들을 포함하여"]}]},{"ko":"그렇다면 무엇이 정확히 웹 사이트를 접근 가능하게 만들까?","en":"So what exactly ___[make] a website accessible?","ans":["makes"],"part":0,"why":["의문사 what(무엇)이 주어이고 단수 취급이라 현재형 makes(만든다)를 써요. [5형식]"],"jj":[{"e":["So what exactly makes","a website accessible?"],"k":["그렇다면 무엇이 정확히 만들까","웹 사이트를 접근 가능하게"]}]},{"ko":"여기 접근성 있는 웹 사이트들의 몇 가지 공통점이 있다.","en":"Here ___[be] some common features of accessible websites.","ans":["are"],"part":0,"why":["Here(여기에) 뒤 주어 some common features(몇몇 공통 특징)가 복수라 are(이다)를 써요. [장소부사(구) 전치]"],"jj":[{"e":["Here are some common features","of accessible websites."],"k":["여기 몇 가지 공통점이 있다","접근성 있는 웹 사이트들의"]}]},{"ko":"텍스트와 함께, 대부분의 웹 사이트는 이미지와 같은 다른 형식의 정보를 포함한다.","en":"Along with text, most websites ___[include] other forms of information, such as images.","ans":["include"],"part":1,"why":["주어 most websites(대부분의 웹사이트)가 복수이고 현재 시제라 동사원형 include(포함하다)를 써요. [most ~]"],"jj":[{"e":["Along with text,","most websites include other forms of information,","such as images."],"k":["텍스트와 함께","대부분의 웹 사이트는 다른 형식의 정보를 포함한다","이미지와 같은"]}]},{"ko":"때로는 그러한 시각적 정보가 텍스트를 이해하는 데 중요하다. 이는 시각 장애를 가진 사용자에게 문제이다.","en":"Sometimes such visual information ___[be] important for ___[understand] the text. This ___[be] a problem for users with visual disabilities.","ans":["is","understanding","is"],"part":1,"why":["주어 such visual information(그런 시각 정보)이 셀 수 없는 단수 취급이라 is(이다)를 써요. [한정사 such]","전치사 for(~을 위해) 뒤에는 동명사 understanding(이해하는 것)처럼 -ing를 써요. [전치사의 목적어]","주어 This(이것)가 단수이고 현재 시제라 is(이다)를 써요."],"jj":[{"e":["Sometimes such visual information is important","for understanding the text."],"k":["때로는 그러한 시각적 정보가 중요하다","텍스트를 이해하는 데"]},{"e":["This is a problem","for users with visual disabilities."],"k":["이는(=이미지 같은 시각적 정보는) 문제이다","시각 장애를 가진 사용자에게"]}]},{"ko":"그들이 웹 사이트에 접속할 때, 그들은 종종 ‘스크린 리더’라 불리는 프로그램을 사용하는데, 이것은 온라인 텍스트를 소리 내어 읽어 준다. 그러나 이러한 프로그램들은 이미지를 ‘읽을’ 수 없다.","en":"When they ___[go] on a website, they often ___[use] programs ___[call] “screen readers,” which ___[read] online text aloud. However, these programs ___[cannot, “read”] images.","ans":["go","use","called","read","cannot “read”"],"part":1,"why":["when(~할 때)이 이끄는 시간 부사절이고 주어 they(그들)가 복수라서 현재시제 복수형 go(가다)를 써요.","주어 they(그들)가 복수이고 습관을 말하는 현재시제라서 원형 use(사용하다)를 써요.","programs(프로그램들)가 ‘불리는’ 대상이라 수동의 과거분사 called(불리는)가 뒤에서 꾸며요. [명사를 수식하는 과거분사구]","which(~하는) 뒤 동사는 선행사 programs(프로그램들)에 수일치해서 복수형 read(읽다)를 써요. [계속적 용법의 관계대명사]","조동사 cannot(~할 수 없다) 뒤에는 동사원형 read(읽다)가 와서 ‘~할 수 없다’가 돼요."],"star":1,"jj":[{"e":["When they go on a website,","they often use programs","called “screen readers,”","which read online text aloud."],"k":["그들이 웹 사이트에 접속할 때","그들은 종종 프로그램을 사용한다","‘스크린 리더’라 불리는","그리고 그것은 온라인 텍스트를 소리 내어 읽는다"]},{"e":["However, these programs cannot “read” images."],"k":["그러나 이러한 프로그램들은 이미지를 ‘읽을’ 수 없다"]}]},{"ko":"접근성 있는 웹 사이트는 ‘alt text’라고도 알려진 대체 텍스트를 제공함으로써 이 문제를 해결한다.","en":"Accessible websites ___[solve] this problem by ___[provide] alternative text, also ___[know] as “alt text.”","ans":["solve","providing","known"],"part":1,"why":["주어 websites(웹사이트들)가 복수이고 현재의 일을 말하므로 복수형 solve(해결하다)를 써요.","전치사 by(~함으로써) 뒤에는 동사 대신 동명사(-ing)가 와서 providing(제공하기)이에요. [전치사의 목적어]","text(텍스트)가 ‘알려진’ 대상이라 수동의 과거분사 known(알려진)을 써요(also known as(~라고도 알려진)). [also known as ~]"],"jj":[{"e":["Accessible websites solve this problem","by providing alternative text,","also known as “alt text.”"],"k":["접근성 있는 웹 사이트는 이 문제를 해결한다","대체 텍스트를 제공함으로써","‘alt text’라고도 알려진"]}]},{"ko":"대체 텍스트는 비문자 정보에 대한 간단한 설명이다.","en":"Alt text ___[be] a brief description of non-textual information.","ans":["is"],"part":1,"why":["주어 Alt text(대체 텍스트)가 3인칭 단수이고 현재의 사실이라 be동사 is(~이다)를 써요."],"jj":[{"e":["Alt text is a brief description","of non-textual information."],"k":["대체 텍스트는 간단한 설명이다","비문자 정보에 대한"]}]},{"ko":"예를 들어, 만약 이미지가 한 무리의 학생들을 보여 준다면, 그것의 대체 텍스트는 이미지에 얼마나 많은 학생들이 있으며 그들이 무엇을 하고 있는지 설명할 것이다.","en":"For instance, if an image ___[show] a group of students, its alt text ___[will, explain] how many students ___[be] in the image and what they ___[do].","ans":["shows","would explain","are","are doing"],"part":1,"why":["if(만약 ~라면) 조건절은 미래도 현재시제로 쓰고, 주어 an image(이미지 하나)가 단수라서 shows(보여 주다)예요.","‘~할 것이다’를 would(~할 것이다)로 부드럽게 말했고, would 뒤는 동사원형 explain(설명하다)이에요.","how many students(몇 명의 학생)가 주어이고 복수라서 be동사 are(~이 있다)를 써요. [간접의문문 & 병렬연결]","‘~하고 있다’는 현재진행형이라 be동사 are(~이다) + doing(하는 중)인 -ing형을 써요."],"star":1,"jj":[{"e":["For instance, if an image shows a group of students,","its alt text would explain","how many students are in the image","and what they are doing."],"k":["예를 들어 만약 이미지가 한 무리의 학생들을 보여 준다면","그것의 대체 텍스트는 설명할 것이다","이미지에 얼마나 많은 학생들이 있는지","그리고 그들이 무엇을 하고 있는지"]}]},{"ko":"스크린 리더는 이 대체 텍스트를 감지하고 소리 내어 읽어 줄 수 있다.","en":"Screen readers ___[can, detect] this alt text and ___[read] it aloud.","ans":["can detect","read"],"part":1,"why":["조동사 can(~할 수 있다) 뒤에는 동사원형 detect(감지하다)를 써요. [병렬연결]","and(그리고)로 이어진 병렬이라 can(~할 수 있다) 뒤 동사원형 detect(감지하다)와 같은 형태 read(읽다)를 써요."],"jj":[{"e":["Screen readers can detect this alt text","and read it aloud."],"k":["스크린 리더는 이 대체 텍스트를 감지할 수 있다","그리고 그것을 소리 내어 읽어 줄 수 있다"]}]},{"ko":"이러한 방식으로, 대체 텍스트는 시각 장애를 가진 사람들이 웹 사이트에서 더 많은 정보에 접근할 수 있도록 보장한다.","en":"This way, alt text ___[ensure] that people with visual disabilities ___[can, access] more of the information on a website.","ans":["ensures","can access"],"part":1,"why":["주어 alt text(대체 텍스트)가 3인칭 단수 현재라서 동사에 -s를 붙인 ensures(보장하다)예요. [접속사 that]","that(~라는)절 안에서 조동사 can(~할 수 있다) 뒤라 동사원형 access(접근하다)를 써요."],"jj":[{"e":["This way, alt text ensures","that people with visual disabilities can access more of the information","on a website."],"k":["이러한 방식으로 대체 텍스트는 보장한다","시각 장애를 가진 사람들이 더 많은 정보에 접근할 수 있도록","웹 사이트에서"]}]},{"ko":"일부 경우에, 음성 콘텐츠는 접근되거나 이해될 수 없다.","en":"In some cases, audio content ___[cannot, access] or ___[understand].","ans":["cannot be accessed","understood"],"part":2,"why":["audio content(오디오 콘텐츠)가 ‘접근되는’ 대상이라 수동태 cannot(~할 수 없다) + be동사 + p.p.예요. [수동태 & 병렬연결]","or(또는)로 accessed(접근되는)와 병렬이라 수동의 과거분사 understood(이해되는)를 써요."],"jj":[{"e":["In some cases,","audio content cannot be accessed or understood."],"k":["일부 경우에","음성 콘텐츠는 접근되거나 이해될 수 없다"]}]},{"ko":"어떤 사람들은 청각 장애를 가지고 있을 수도 있는데 반하여, 다른 사람들은 조용한 도서관과 같이 그들이 음성을 들을 수 없는 장소에 있을지도 모른다.","en":"Some people ___[may, have] hearing disabilities, while others ___[might, be] in places where they ___[can’t, listen] to audio, such as a quiet library.","ans":["may have","might be","can’t listen"],"part":2,"why":["조동사 may(~일 수도 있다) 뒤에는 동사원형 have(가지다)를 써서 ‘~일 수도 있다’가 돼요.","조동사 might(~일지도 모른다) 뒤에는 동사원형 be(있다)를 써요.","where(~하는 곳)절 안에서 can’t(~할 수 없다) 뒤라 동사원형 listen(듣다)을 써요(listen to(~을 듣다)). [관계부사 where]"],"star":1,"jj":[{"e":["Some people may have hearing disabilities,","while others might be in places","where they can't listen to audio,","such as a quiet library."],"k":["어떤 사람들은 청각 장애를 가지고 있을 수도 있다","반면 다른 사람들은 장소에 있을지도 모른다","그들이 음성을 들을 수 없는","조용한 도서관과 같은"]}]},{"ko":"그러므로 접근성 있는 웹 사이트들은 흔히 음성 형식으로 제시되는 정보에 접근할 수 있는 다른 방법들을 제공한다.","en":"Therefore, accessible websites ___[often, offer] other ways ___[access] information that ___[present] in audio form.","ans":["often offer","to access","is presented"],"part":2,"why":["주어 websites(웹사이트들)가 복수라서 현재형 동사원형 offer(제공하다)를 쓰고 often(자주)은 그 앞 부사예요.","other ways(다른 방법들)를 뒤에서 꾸미는 형용사적 용법 to부정사 to access(접근하다)예요. [형용사적 용법의 to부정사]","선행사 information(정보)이 단수이고 ‘제시되는’ 대상이라 수동태 is presented(제시된다)예요. [주격 관계대명사]"],"star":1,"jj":[{"e":["Therefore, accessible websites often offer other ways","to access information","that is presented in audio form."],"k":["그러므로 접근성 있는 웹 사이트들은 흔히 다른 방법들을 제공한다","정보에 접근할 수 있는","음성 형식으로 제시되는"]}]},{"ko":"예를 들어, 그것들은 사용자가 이 정보에 접근하는 데 도움이 될 수 있는 대본이나 자막을 제공할 수도 있다.","en":"For example, they ___[may, provide] transcripts or captions that ___[can, help] users ___[access] this information.","ans":["may provide","can help","access"],"part":2,"why":["조동사 may(~할 수도 있다) 뒤에는 동사원형 provide(제공하다)를 써요.","관계대명사 that(~하는)절 안에서 조동사 can(~할 수 있다) 뒤라 동사원형 help(돕다)를 써요. [주격 관계대명사]","help(돕다)는 목적어 뒤에 동사원형(또는 to부정사)이 오니까 access(접근하다)를 써요. [5형식]"],"jj":[{"e":["For example, they may provide transcripts or captions","that can help users access this information."],"k":["예를 들어 그것들은 대본이나 자막을 제공할 수도 있다","사용자가 이 정보에 접근하는 데 도움이 될 수 있는"]}]},{"ko":"대본은 전체 음성 콘텐츠의 텍스트 버전인 반면, 자막은 영상이 재생될 때 영상 안에 나타나는 음성의 텍스트 버전이다.","en":"Transcripts ___[be] text versions of the entire audio content, while captions ___[be] text versions of the audio that ___[appear] in a video as it ___[play].","ans":["are","are","appear","plays"],"part":2,"why":["주어 Transcripts(대본)가 복수라서 be동사 are(~이다)를 써요.","while(~인 반면) 뒤 절의 주어 captions(자막)가 복수라서 be동사 are(~이다)를 써요. [접속사 while]","that(~하는)절의 선행사 핵심어 versions(버전들)가 복수라서 복수동사 appear(나타나다)를 써요. [주격 관계대명사 & 동사의 수일치]","as(~할 때)절의 주어 it(그것)이 단수 현재시제라서 plays(재생되다)예요. [접속사 as]"],"jj":[{"e":["Transcripts are text versions of the entire audio content,","while captions are text versions of the audio","that appear in a video as it plays."],"k":["대본은 전체 음성 콘텐츠의 텍스트 버전이다","반면 자막은 음성의 텍스트 버전이다","영상이 재생될 때 영상 안에 나타나는"]}]},{"ko":"자막은 발화된 단어의 텍스트 버전뿐만 아니라 영상 내의 음악과 다른 소리들에 대한 설명도 포함한다.","en":"Captions ___[include] not only the text version of the ___[speak] words but also descriptions of the music and other sounds in the video.","ans":["include","spoken"],"part":2,"why":["주어 Captions(자막)가 복수 현재라서 동사원형 include(포함하다)를 써요. [not only A but also B]","words(말)가 ‘말해진’ 대상이라 수동의 과거분사 spoken(말해진)이 앞에서 꾸며요. [분사형 형용사]"],"jj":[{"e":["Captions include not only the text version of the spoken words","but also descriptions of the music and other sounds","in the video."],"k":["자막은 발화된 단어의 텍스트 버전을 포함할 뿐만 아니라","음악과 다른 소리들에 대한 설명도 포함한다","영상 내의"]}]},{"ko":"보고 듣기에 쉬운 콘텐츠\n시각 장애를 지니고 있는 것은 반드시 한 사람이 전혀 보지 못한다는 것을 의미하지는 않는다.","en":"Content That ___[be] Easy ___[see] and ___[hear]\n___[Have] a visual disability ___[not, necessarily, mean] a person ___[can’t, see] at all.","ans":["Is","to See","Hear","Having","doesn’t necessarily mean","can’t see"],"part":3,"why":["관계대명사 That(~하는) 뒤 be동사가 선행사 Content(내용)에 맞춰 Is(~이다)예요.","Easy(쉬운)를 꾸며 ‘~하기에’를 나타내는 to부정사 To See(보기)예요.","and(그리고)로 To See(보기)와 병렬이고 두 번째 to(~하기)가 생략돼 동사원형 Hear(듣다)예요.","문장의 주어 자리라 동명사 Having(~하는 것)을 써요. [동명사구 주어 & 수일치]","동명사 주어는 단수라 doesn’t(~하지 않는다)이고, 뒤에 동사원형 mean(의미하다)이 와서 부분부정이에요.","명사절 안에서 can’t(~할 수 없다) 뒤라 동사원형 see(보다)를 써요. [명사절 접속사 that의 생략]"],"star":1,"jj":[{"e":["Content That Is Easy to See and Hear"],"k":["보고 듣기에 쉬운 콘텐츠"]},{"e":["Having a visual disability","doesn't necessarily mean","a person can't see at all."],"k":["시각 장애를 지니고 있는 것은","반드시 의미하지는 않는다","한 사람이 전혀 보지 못한다는 것을"]}]},{"ko":"많은 노인들을 포함해서 일부 사람들은 그저 좋지 않은 시력을 가지고 있다. 이는 그들이 읽는 것을 어렵게 만든다.","en":"Some people, including many elderly people, simply ___[have] poor eyesight. This ___[make] it difficult for them ___[read].","ans":["have","makes","to read"],"part":3,"why":["주어 Some people(일부 사람들)이 복수이고 현재 사실이라 현재형 have(가지고 있다)를 써요.","주어 This(이것)가 3인칭 단수이고 현재 일이라 makes(만들어 준다)로 써요.","가목적어 it(그것) 뒤 진목적어 자리라 ‘for(~가)+사람+to부정사’로 써요."],"star":1,"jj":[{"e":["Some people, including many elderly people,","simply have poor eyesight."],"k":["많은 노인들을 포함해서 일부 사람들은","그저 좋지 않은 시력을 가지고 있다"]},{"e":["This makes it difficult","for them to read."],"k":["이는(=좋지 않은 시력은) 어렵게 만든다","그들이 읽는 것을"]}]},{"ko":"이러한 이유로, 접근성 있는 웹 사이트는 텍스트 색과 대조를 이루는 배경 색을 지니고 있다.","en":"For this reason, accessible websites ___[have] a background color that ___[contrast] with the color of their text.","ans":["have","contrasts"],"part":3,"why":["주어 accessible websites(접근 가능한 웹사이트)가 복수라 have(가지고 있다)를 써요.","관계대명사 that(~하는)의 선행사 a background color(배경색)가 단수라 contrasts(대조를 이룬다)로 써요. [주격 관계대명사]"],"jj":[{"e":["For this reason, accessible websites have a background color","that contrasts with the color of their text."],"k":["이러한 이유로 접근성 있는 웹 사이트는 배경 색을 지니고 있다","텍스트 색과 대조를 이루는"]}]},{"ko":"이는 대부분의 사람들이 보기에 텍스트를 충분히 명확하게 만들어 준다.","en":"This ___[make] the text clear enough for most people ___[see].","ans":["makes","to see"],"part":3,"why":["주어 This(이것)가 3인칭 단수이고 현재 일이라 makes(만들어 준다)로 써요. [5형식]","‘형용사+enough(충분히)+for(~가) 사람+to부정사’는 ‘~하기에 충분히 …한’이에요."],"jj":[{"e":["This makes the text clear enough","for most people to see."],"k":["이는(=대조되는 배경 색은) 텍스트를 충분히 명확하게 만들어 준다","대부분의 사람들이 보기에"]}]},{"ko":"음성 콘텐츠에 관해 말하자면, 접근성 있는 웹 사이트는 사용자가 배경음의 음량을 조절하거나 완전히 끌 수 있도록 해준다.","en":"As for audio content, accessible websites ___[allow] users ___[adjust] the volume of background sound or ___[turn] it off altogether.","ans":["allow","to adjust","to turn"],"part":3,"why":["주어 accessible websites(접근 가능한 웹사이트)가 복수이고 현재형이라 allow(허락한다)를 써요. [5형식 & 병렬연결]","allow(허락하다)+목적어 뒤 목적격보어는 to부정사라 to adjust(조절하는 것)로 써요.","or(또는)로 이어진 두 번째 to부정사라 to turn(끄는 것)으로 맞춰 써요. [구동사 turn ~ off]"],"jj":[{"e":["As for audio content,","accessible websites allow users","to adjust the volume of background sound","or to turn it off altogether."],"k":["음성 콘텐츠에 관해서는","접근성 있는 웹 사이트는 사용자가 하도록 허용한다","배경음의 음량을 조절하도록","또는 그것을 완전히 끄도록"]}]},{"ko":"이는 청각 장애가 있는 사용자와 없는 사용자 모두에게 그들이 사이트를 사용하는 동안 그들의 경험에 대한 더 많은 통제권을 준다.","en":"This ___[give] users both with and without ___[hear] difficulties more control over their experience while they ___[use] the sites.","ans":["gives","hearing","are using"],"part":3,"why":["주어 This(이것)가 3인칭 단수이고 현재 일이라 gives(준다)로 써요. [4형식]","명사 difficulties(어려움) 앞에서 ‘듣는 것의’라는 뜻으로 꾸미는 -ing 형태 hearing(청각의)을 써요.","while(~하는 동안)절에서 지금 진행 중인 동작이라 현재진행형 are using(사용하고 있다)이에요."],"jj":[{"e":["This gives users both with and without hearing difficulties","more control over their experience","while they are using the sites."],"k":["이는(=음량 조절 기능은) 청각 장애가 있는 사용자와 없는 사용자 모두에게 준다","그들의 경험에 대한 더 많은 통제권을","그들이 사이트를 사용하는 동안"]}]},{"ko":"키보드를 사용하는 완전한 탐색\n일부 사용자들은 그들의 손의 움직임을 제한하는 장애를 가지고 있다.","en":"Complete Navigation ___[Use] the Keyboard\nSome users ___[have] disabilities that ___[limit] the movement of their hands.","ans":["Using","have","limit"],"part":4,"why":["명사 Navigation(탐색)을 뒤에서 꾸미는 현재분사 Using(~을 사용하는)이에요.","주어 Some users(일부 사용자들)가 복수라 현재형 have(가지고 있다)를 써요.","관계대명사 that(~하는)의 선행사 disabilities(장애)가 복수라 복수 동사 limit(제한한다)로 써요. [주격 관계대명사]"],"jj":[{"e":["Complete Navigation Using the Keyboard"],"k":["키보드를 사용하는 완전한 탐색"]},{"e":["Some users have disabilities","that limit the movement of their hands."],"k":["일부 사용자들은 장애를 가지고 있다","그들의 손의 움직임을 제한하는"]}]},{"ko":"그들은 웹 사이트를 탐색하기 위해 마우스보다는 키보드에 의존한다.","en":"They ___[rely] on their keyboards, rather than a mouse, ___[navigate] websites.","ans":["rely","to navigate"],"part":4,"why":["주어 They(그들)가 복수이고 현재 습관이라 rely(의존한다)를 써요.","‘~하기 위해’라는 목적은 부사적 용법의 to부정사로 나타내요."],"jj":[{"e":["They rely on their keyboards,","rather than a mouse,","to navigate websites."],"k":["그들은 키보드에 의존한다","마우스보다는","웹 사이트를 탐색하기 위해"]}]},{"ko":"접근성 있는 웹 사이트에서, 사용자는 키보드만을 사용하여 사이트에 있는 모든 것에 접근할 수 있다.","en":"On accessible websites, users ___[can, access] everything on the site ___[use] only a keyboard.","ans":["can access","using"],"part":4,"why":["조동사 can(~할 수 있다) 뒤에는 동사원형이라 can access(접근할 수 있다)로 써요.","앞 절에 덧붙는 ‘~하면서(부대상황)’는 현재분사 using(사용하는)으로 써요."],"jj":[{"e":["On accessible websites,","users can access everything on the site","using only a keyboard."],"k":["접근성 있는 웹 사이트에서","사용자는 사이트에 있는 모든 것에 접근할 수 있다","키보드만을 사용하여"]}]},{"ko":"이는 링크, 버튼 그리고 정보가 입력되는 공간인 필드가 키보드 탐색을 통해 접근될 수 있다는 것을 의미한다.","en":"This ___[mean] that links, buttons, and fields, which ___[be] spaces where information ___[enter], ___[can, access] through keyboard navigation.","ans":["means","are","is entered","can be accessed"],"part":4,"why":["주어 This(이것)가 3인칭 단수이고 현재형이라 means(의미한다)로 써요. [접속사 that]","which(~인)의 선행사 fields(입력란)가 복수라서 be동사는 are(~이다)예요.","정보가 입력되는 것이라 수동태이고 information(정보)은 단수라 is entered(입력된다)로 써요.","링크 등이 접근되는 것이라 수동태 can be(~될 수 있다)+p.p.로 써요."],"star":1,"jj":[{"e":["This means","that links, buttons, and fields,","which are spaces where information is entered,","can be accessed through keyboard navigation."],"k":["이는(=키보드만으로 모든 것에 접근할 수 있다는 것은) 의미한다","링크, 버튼 그리고 필드가","정보가 입력되는 공간인","키보드 탐색을 통해 접근될 수 있다는 것을"]}]},{"ko":"사용자는 스페이스 바, 화살표 키, 엔터 키 그리고 탭 키와 같은 키를 사용함으로써 웹 사이트를 탐색한다.","en":"Users ___[navigate] the websites by ___[make] use of keys such as the space bar, the arrow keys, the enter key, and the tab key.","ans":["navigate","making"],"part":4,"why":["주어 Users(사용자들)가 복수이고 현재형이라 navigate(탐색한다)를 써요.","전치사 by(~함으로써) 뒤에는 동명사가 와서 making use of(~을 이용하는)로 써요. [전치사의 목적어 / make use of ~]"],"jj":[{"e":["Users navigate the websites","by making use of keys","such as the space bar, the arrow keys, the enter key, and the tab key."],"k":["사용자는 웹 사이트를 탐색한다","키를 사용함으로써","스페이스 바, 화살표 키, 엔터 키 그리고 탭 키와 같은"]}]},{"ko":"예를 들어, 그들은 웹 페이지의 한 부분에서 다른 부분으로 뛰어넘기 위해 탭 키를 사용할 수 있다.","en":"For example, they ___[can, use] the tab key ___[jump] from one part of a web page to another.","ans":["can use","to jump"],"part":4,"why":["조동사 can(~할 수 있다) 뒤에는 동사원형이라 can use(사용할 수 있다)로 써요.","‘~하기 위해’라는 목적은 부사적 용법의 to부정사로 나타내요."],"jj":[{"e":["For example, they can use the tab key","to jump from one part of a web page to another."],"k":["예를 들어 그들은 탭 키를 사용할 수 있다","웹 페이지의 한 부분에서 다른 부분으로 뛰어넘기 위해"]}]},{"ko":"장애를 가진 사용자와 일시적으로 손을 다친 사용자 모두가 이러한 종류의 탐색으로부터 득을 본다.","en":"Both users with disabilities and those with temporarily ___[injure] hands ___[can, benefit] from this kind of navigation.","ans":["injured","can benefit"],"part":4,"why":["hands(손)는 다치게 된 대상이라 수동의 뜻인 과거분사 injured(다친)로 꾸며요. [분사형 형용사]","조동사 can(~할 수 있다) 뒤에는 동사원형이라 can benefit(혜택을 얻을 수 있다)으로 써요."],"jj":[{"e":["Both users with disabilities and those with temporarily injured hands","can benefit from this kind of navigation."],"k":["장애를 가진 사용자와 일시적으로 손을 다친 사용자 모두가","이러한 종류의 탐색으로부터 득을 본다"]}]},{"ko":"정보를 전달하는 색상 이외의 지표들\n색맹은 흔한 시각 장애이다. 색맹인 사람들은 몇몇 색들을 구별하는 것을 어렵다고 여긴다.","en":"Indicators Other than Color That ___[Convey] Information\nColor blindness ___[be] a common visual disability. People with color blindness ___[find] it difficult ___[tell] some colors apart.","ans":["Convey","is","find","to tell"],"part":5,"why":["선행사 Indicators(지표들)가 복수라 관계대명사 that(~하는) 뒤 복수 동사 Convey(전달한다)를 써요.","주어 Color blindness(색맹)가 단수이고 현재 사실이라 is(이다)를 써요.","주어 People(사람들)이 복수이고 현재형이라 find(여긴다)를 써요. [5형식 & 가목적어 it]","가목적어 it(그것)의 진목적어 자리라 명사적 용법 to부정사 to tell(구별하다)로 써요. [구동사 tell ~ apart]"],"star":1,"jj":[{"e":["Indicators Other than Color That Convey Information"],"k":["정보를 전달하는 색상 이외의 지표들"]},{"e":["Color blindness is a common visual disability."],"k":["색맹은 흔한 시각 장애이다"]},{"e":["People with color blindness","find it difficult","to tell some colors apart."],"k":["색맹인 사람들은","어렵다고 여긴다","몇몇 색들을 구별하는 것을"]}]},{"ko":"이는 특히 그래프와 차트가 정보 세트들 간의 차이를 나타내기 위해 색상만을 사용할 때 문제를 일으킬 수 있다.","en":"This ___[can, cause] problems, especially when graphs and charts only ___[use] colors ___[show] the differences between sets of information.","ans":["can cause","use","to show"],"part":5,"why":["can(~할 수 있다) 뒤에는 동사원형 cause(일으키다)가 와요.","주어 graphs(그래프)와 charts(차트)가 복수이고 현재 일이라 동사원형 use(사용하다)예요.","‘~하기 위해’라는 목적의 부사적 용법 to부정사 to show(보여 주다)예요. [부사적 용법의 to부정사]"],"jj":[{"e":["This can cause problems,","especially when graphs and charts only use colors","to show the differences between sets of information."],"k":["이는(=색을 구별하기 어려운 것은) 문제를 일으킬 수 있다","특히 그래프와 차트가 색상만을 사용할 때","정보 세트들 간의 차이를 보여 주기 위해"]}]},{"ko":"접근성 있는 웹 사이트는 색상과 더불어 다른 지표들도 사용한다.","en":"Accessible websites ___[use] other indicators along with the colors.","ans":["use"],"part":5,"why":["주어 Accessible websites(접근성 있는 웹 사이트)가 복수, 현재 일이라 동사원형 use(사용하다)예요."],"jj":[{"e":["Accessible websites use other indicators","along with the colors."],"k":["접근성 있는 웹 사이트는 다른 지표들도 사용한다","색상과 더불어"]}]},{"ko":"예를 들어, 녹색 선은 점선일 수도 있는 반면에, 파란색 선은 실선이다.","en":"For example, a line in green ___[may, also, dot], while a line in blue ___[be] solid.","ans":["may also be dotted","is"],"part":5,"why":["선이 ‘점선’인 상태라 may(~일 수도 있다) 뒤에 be+과거분사 dotted(점이 찍힌)를 써요. [분사형 형용사]","주어 a line in blue(파란색 선)가 단수라 be동사는 is(~이다)예요."],"jj":[{"e":["For example, a line in green may also be dotted,","while a line in blue is solid."],"k":["예를 들어 녹색 선은 점선일 수도 있다","반면에 파란색 선은 실선이다"]}]},{"ko":"이는 모든 이가 두 선을 구별할 수 있도록 한다.","en":"This ___[ensure] that everyone ___[can, tell] the two lines apart.","ans":["ensures","can tell"],"part":5,"why":["주어 This(이것)가 단수이고 현재 일이라 ensures(보장하다)처럼 동사에 3인칭 단수 어미를 붙여요. [접속사 that]","that(~라는 것)절 안에서 can(~할 수 있다) 뒤에 동사원형 tell(구별하다)이 와요."],"jj":[{"e":["This ensures","that everyone can tell the two lines apart."],"k":["이는(=색상 외 지표를 함께 쓰는 것은) 보장한다","모든 이가 두 선을 구별할 수 있도록"]}]},{"ko":"웹 사이트의 접근성 특징들은 단지 장애가 있는 사람들만을 돕는 것이 아니다.","en":"The accessibility features of websites ___[not, just, help] people with disabilities.","ans":["don’t just help"],"part":5,"why":["복수 주어 features(특징들)라 don’t(~않다) 뒤에 동사원형 help(돕다)가 와요."],"jj":[{"e":["The accessibility features of websites","don't just help people with disabilities."],"k":["웹 사이트의 접근성 특징들은","단지 장애가 있는 사람들만을 돕는 것이 아니다"]}]},{"ko":"그것들은 능력이나 상황과 상관없이 모두에게 온라인 경험을 더 용이하게 만들어 줄 수 있다.","en":"They ___[can, make] online experiences easier for everyone, regardless of abilities or situations.","ans":["can make"],"part":5,"why":["can(~할 수 있다) 뒤에 동사원형 make(만들다)가 오고, make(만들다)+목적어+형용사 구조예요. [5형식]"],"jj":[{"e":["They can make online experiences easier","for everyone,","regardless of abilities or situations."],"k":["그것들은 온라인 경험을 더 용이하게 만들어 줄 수 있다","모두에게","능력이나 상황과 상관없이"]}]},{"ko":"웹 사이트가 탐색하고 이해하기에 더 쉬울 때, 우리는 더 차별 없는 온라인 경험으로부터 득을 볼 수 있다.","en":"When websites ___[be] easy ___[navigate] and ___[understand], we ___[can, all, benefit] from a more inclusive online experience.","ans":["are","to navigate","understand","can all benefit"],"part":5,"why":["주어 websites(웹 사이트)가 복수라 be동사는 are(~이다)예요.","형용사 easy(쉬운)를 꾸미는 to부정사라 to navigate(탐색하다)예요. [부사적 용법의 to부정사 & 병렬연결]","and(그리고)로 연결되어 to(~하기)가 생략된 동사원형 understand(이해하다)예요.","can(~할 수 있다)과 동사 사이에 all(모두)이 끼어도 뒤는 동사원형 benefit(득을 보다)예요."],"jj":[{"e":["When websites are easy to navigate and understand,","we can all benefit","from a more inclusive online experience."],"k":["웹 사이트가 탐색하고 이해하기에 더 쉬울 때","우리는 모두 득을 볼 수 있다","더 차별 없는 온라인 경험으로부터"]}]},{"ko":"웹을 더 문화적으로 접근 가능하게 만들기\n읽기와 쓰기 체계는 문화마다 다르다.","en":"Culture Notes: ___[Make] the Web More Culturally Accessible\n___[Read] and ___[write] systems ___[be] different across cultures.","ans":["Making","Reading","writing","are"],"part":6,"why":["제목에서 ‘~하기’라는 뜻의 동명사(-ing) Making(만들기)을 써요.","‘~하기’라는 뜻의 동사파생명사 Reading(읽기)이 주어 역할을 해요. [병렬연결 & 동사파생명사]","and(그리고)로 연결된 명사라 같은 -ing형 writing(쓰기)이에요.","Reading and writing systems(읽기와 쓰기 체계)는 복수 주어라 be동사는 are(~이다)예요."],"jj":[{"e":["Culture Notes: Making the Web More Culturally Accessible"],"k":["웹을 더 문화적으로 접근 가능하게 만들기"]},{"e":["Reading and writing systems are different","across cultures."],"k":["읽기와 쓰기 체계는 다르다","문화마다"]}]},{"ko":"서양 문화 출신의 사람들은 왼쪽에서 오른쪽으로 읽고 쓰는 반면, 일부 중동 문화 출신의 사람들은 오른쪽에서 왼쪽으로 읽고 쓴다.","en":"People from Western cultures ___[read] and ___[write] from left to right, while those from some Middle Eastern cultures ___[read] and ___[write] from right to left.","ans":["read","write","read","write"],"part":6,"why":["주어 People(사람들)이 복수, 현재 일이라 동사원형 read(읽다)예요. [병렬연결]","and(그리고)로 연결된 복수 동사라 동사원형 write(쓰다)예요.","주어 those(사람들)가 복수, 현재 일이라 동사원형 read(읽다)예요. [대명사 those]","and(그리고)로 연결된 복수 동사라 동사원형 write(쓰다)예요."],"jj":[{"e":["People from Western cultures read and write from left to right,","while those from some Middle Eastern cultures","read and write from right to left."],"k":["서양 문화 출신의 사람들은 왼쪽에서 오른쪽으로 읽고 쓴다","반면 일부 중동 문화 출신의 사람들은","오른쪽에서 왼쪽으로 읽고 쓴다"]}]},{"ko":"일본과 같은 일부 동양 문화 출신 사람들은 위에서 아래로 읽고 쓴다.","en":"People from some Eastern cultures, like that of Japan, ___[read] and ___[write] from top to bottom.","ans":["read","write"],"part":6,"why":["주어 People(사람들)이 복수, 현재 일이라 동사원형 read(읽다)예요. [병렬연결]","and(그리고)로 연결된 복수 동사라 동사원형 write(쓰다)예요."],"jj":[{"e":["People from some Eastern cultures,","like that of Japan,","read and write from top to bottom."],"k":["일부 동양 문화 출신 사람들은","일본과 같은","위에서 아래로 읽고 쓴다"]}]},{"ko":"몇몇 세계적인 웹 사이트는 이러한 차이를 고려하고 다른 지역의 사람들을 위해 그들의 웹 사이트를 조정한다.","en":"Some global websites ___[take] these differences into consideration and ___[adjust] their websites for people in different regions.","ans":["take","adjust"],"part":6,"why":["주어 websites(웹 사이트)가 복수, 현재 일이라 동사원형 take(취하다)예요. [take ~ into consideration / 병렬연결]","and(그리고)로 연결된 복수 동사라 동사원형 adjust(조정하다)예요."],"jj":[{"e":["Some global websites take these differences into consideration","and adjust their websites","for people in different regions."],"k":["몇몇 세계적인 웹 사이트는 이러한 차이를 고려한다","그리고 그들의 웹 사이트를 조정한다","다른 지역의 사람들을 위해"]}]},{"ko":"글이 오른쪽에서 왼쪽으로 읽히는 국가에서는 웹 사이트의 검색 버튼이 왼쪽에 있고 로고가 오른쪽에 있다.","en":"In countries where text ___[read] from right to left, the website’s search button ___[be] on the left and the logo ___[be] on the right.","ans":["is read","is","is"],"part":6,"why":["text(글)이 ‘읽히는’ 대상이라 수동태 be+p.p.인 is read(읽히다)이고 주어가 단수예요. [관계부사 where]","주어 search button(검색 버튼)이 단수라 be동사는 is(~이다)예요.","주어 logo(로고)가 단수라 be동사는 is(~이다)예요."],"star":1,"jj":[{"e":["In countries where text is read from right to left,","the website's search button is on the left","and the logo is on the right."],"k":["글이 오른쪽에서 왼쪽으로 읽히는 국가에서는","웹 사이트의 검색 버튼이 왼쪽에 있다","그리고 로고가 오른쪽에 있다"]}]},{"ko":"만약 당신이 동일한 웹 사이트를 다른 언어 설정으로 방문한다면, 당신은 다른 구성 방식을 보게 될 것이다.","en":"If you ___[visit] the same websites in a different language setting, you ___[will, see] a different format.","ans":["visit","will see"],"part":6,"why":["조건 if(~라면)절은 미래 뜻이어도 현재시제 visit(방문하다)을 써요. [접속사 if & 현재시제]","앞으로 일어날 일이라 will(~일 것이다)+동사원형 see(보다)예요."],"jj":[{"e":["If you visit the same websites in a different language setting,","you will see a different format."],"k":["만약 당신이 동일한 웹 사이트를 다른 언어 설정으로 방문한다면","당신은 다른 구성 방식을 보게 될 것이다"]}]}]}]};
